mapper.select:
SELECT b.references FROM references_template_mapping a JOIN mod_references b ON a.references_id = b.id WHERE a.template_name = #{templateName}
AND a.references_name = #{module}
AND b.deleted = 1

SELECT
cancer_title,
note
FROM mod_common_note
WHERE module = #{module}

    AND type = #{type}


    AND type = '通用'


    AND sample_type = #{sampleType}


    AND cancer = #{cancer}

AND deleted = 1

SELECT tumors
FROM cr_related_tumors
WHERE gender = #{gender}
  AND gene = #{gene}
  AND deleted = 0
